<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,can} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('AdsStrategyPanel')
const props=defineProps<{profiles:any[],context?:any,store:string,country:string}>()
const names:Record<string,string>={state:'分时状态',budget:'分时预算',bid:'分时调价',inventory:'库存规则'}
const states:Record<string,string>={waiting:'等待检查',idle:'已检查',pending:'待确认',sending:'提交中',succeeded:'已执行',failed:'失败',unknown:'待核对',conflict:'外部修改'}
const data=ref<any>({templates:[],bindings:[]}),busy=ref(false),dialog=ref(false),readOnly=ref(false),form=ref<any>({}),applying=ref<any>(null),applyStore=ref(''),applyProfile=ref(''),applyCampaign=ref(''),applyGroup=ref(''),q=ref(''),choices=ref<any[]>([]),selected=ref<any[]>([]),options=ref<any>({campaigns:[],groups:[]}),details=ref<any>(null)
const editable=computed(()=>!props.context&&can('advertising','operate'))
const stores=computed(()=>Array.from(new Set(props.profiles.map(p=>p.account))))
const countries=computed(()=>Array.from(new Set(props.profiles.map(p=>p.country==='GB'?'UK':p.country))))
const profiles=computed(()=>props.profiles.filter(p=>p.account===applyStore.value&&(p.country==='GB'?'UK':p.country)===applying.value?.country))
const groups=computed(()=>options.value.groups.filter((g:any)=>!applyCampaign.value||g.campaign_id===applyCampaign.value))
const filtered=computed(()=>choices.value.filter(r=>[r.name,r.asin,r.sku,r.campaign_name].join(' ').toLowerCase().includes(q.value.toLowerCase())))
const templateSearch=ref('')
const createdTime=(value:string|null)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'
const relevant=computed(()=>data.value.templates.filter((t:any)=>t.name.toLowerCase().includes(templateSearch.value.trim().toLowerCase())))
const bindings=(t:any)=>data.value.bindings.filter((b:any)=>b.template_id===t.id&&(b.active||!b.runtime.rolled_back))
const weekdayNames=['周一','周二','周三','周四','周五','周六','周日']
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
async function mutate(path:string,method:string,body?:any){const r=await fetch('/api/advertising'+path,{method,headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:Array.isArray(d.detail)?d.detail.map((v:any)=>v.msg).join('；'):'操作失败');return d}
async function load(){try{const p=new URLSearchParams();if(props.context){p.set('profile_id',props.context.profileId);if(props.context.campaign)p.set('campaign_id',props.context.campaign.id);if(props.context.group)p.set('adgroup_id',props.context.group.id)}data.value=await api('/advertising/strategies?'+p)}catch(e){ElMessage.error((e as Error).message)}}
async function polling(){await load();if(!disposed)timer=setTimeout(polling,15000)}
function newWindow(){return {start:'08:00',end:'23:00',weekdays:[0,1,2,3,4,5,6],dates:[],state:'ENABLED',percent:0,minimum:null,maximum:null}}
function create(kind:string){readOnly.value=false;form.value={name:'',country:'',kind,enabled:true,config:{start:null,end:null,mode:'daily',windows:kind==='inventory'?[]:[newWindow()],baseline:'original',fixed:null,rollback:'original',rollback_value:null,rollback_state:'PAUSED',inventory_fields:['available','receiving','inbound'],threshold:10,restore_threshold:10,inventory_frequency:'hourly',inventory_time:'08:00',execution:'auto'}};dialog.value=true}
function edit(t:any,view=false){form.value=JSON.parse(JSON.stringify(t));readOnly.value=view;dialog.value=true}
async function save(){if(!form.value.country){ElMessage.warning('请选择适用站点');return}if(!form.value.name.trim()){ElMessage.warning('请输入模板名称');return}busy.value=true;try{const {name,country,kind,enabled,config}=form.value;await mutate('/strategies'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',{name,country,kind,enabled,config});dialog.value=false;await load();ElMessage.success('模板已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function toggle(t:any){try{await mutate('/strategies/'+t.id,'PUT',{name:t.name,country:t.country,kind:t.kind,enabled:!t.enabled,config:t.config});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function remove(t:any){try{await ElMessageBox.confirm('删除模板后，已应用对象按模板回调设置处理。','删除策略');await mutate('/strategies/'+t.id,'DELETE');await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function startApply(t:any){applying.value=t;applyStore.value=props.store||stores.value[0]||'';applyProfile.value='';applyCampaign.value='';applyGroup.value='';choices.value=[];selected.value=[];options.value={campaigns:[],groups:[]};if(profiles.value.length===1){applyProfile.value=profiles.value[0].id;await profileChanged()}}
async function profileChanged(){selected.value=[];applyCampaign.value='';applyGroup.value='';if(!applyProfile.value)return;try{options.value=await api('/advertising/create/options?profile_id='+applyProfile.value);await loadChoices()}catch(e){ElMessage.error((e as Error).message)}}
async function loadChoices(){if(!applyProfile.value)return;busy.value=true;selected.value=[];try{const r=await api('/advertising/strategy-options?'+new URLSearchParams({profile_id:applyProfile.value,template_id:applying.value.id,campaign_id:applyCampaign.value,adgroup_id:applyGroup.value}));choices.value=r.rows}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function apply(){busy.value=true;try{await api('/advertising/strategies/'+applying.value.id+'/apply',{profile_id:applyProfile.value,entities:selected.value.map(r=>({kind:r.kind,id:r.id}))});applying.value=null;await load();ElMessage.success('已应用，后台将按站点时间执行')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function unbind(b:any){try{await ElMessageBox.confirm('取消后按模板回调设置处理此对象。','取消应用');await mutate('/strategy-bindings/'+b.id,'DELETE');await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function approve(b:any){try{await api('/advertising/strategy-bindings/'+b.id+'/approve',{});await load();ElMessage.success('已确认本次调整')}catch(e){ElMessage.error((e as Error).message)}}
onMounted(polling);onUnmounted(()=>{disposed=true;if(timer)clearTimeout(timer)});watch(()=>props.context,load)
</script>
<template><section class="panel strategy-panel"><div class="heading"><h3>{{context?'已应用广告策略':'广告策略模板'}}</h3><el-input v-model="templateSearch" clearable placeholder="搜索模板名称" aria-label="搜索模板名称" style="width:240px"/><TableReset table-key="AdsStrategyPanel/templates"/><el-button @click="load">刷新</el-button><el-dropdown v-if="editable" @command="create"><el-button type="primary">添加策略 ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="(name,key) in names" :key="key" :command="key">{{name}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
<el-alert v-if="!data.execution_enabled" title="策略后台尚未启用，当前可以保存和编辑模板。" type="info" :closable="false"/><el-table :data="relevant" border data-width-key="AdsStrategyPanel/templates" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('templates',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('templates',column,event)"><el-table-column column-key="name" label="模板名称" :width="tableWidths.width('templates','name',220)"><template #default="{row}"><el-button link type="primary" @click="edit(row,true)">{{row.name}}</el-button></template></el-table-column><el-table-column column-key="kind" label="类型" :width="tableWidths.width('templates','kind',130)"><template #default="{row}">{{names[row.kind]}}</template></el-table-column><el-table-column column-key="country" prop="country" label="站点" :width="tableWidths.width('templates','country',90)"/><el-table-column column-key="enabled" label="状态" :width="tableWidths.width('templates','enabled',100)"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'暂停'}}</el-tag></template></el-table-column><el-table-column column-key="bindings" label="应用对象" :width="tableWidths.width('templates','bindings',110)"><template #default="{row}"><el-button link @click="details=row">{{bindings(row).length}} 个</el-button></template></el-table-column><el-table-column column-key="owner" prop="owner" label="创建人" :width="tableWidths.width('templates','owner',130)"/><el-table-column column-key="created_at" label="创建时间" :width="tableWidths.width('templates','created_at',190)"><template #default="{row}"><span :title="row.created_at?'':'历史模板未记录创建时间'">{{createdTime(row.created_at)}}</span></template></el-table-column><el-table-column column-key="actions" label="操作" :width="tableWidths.width('templates','actions',260)"><template #default="{row}"><el-button link @click="edit(row,true)">查看</el-button><template v-if="editable"><el-button link type="primary" @click="edit(row)">修改</el-button><el-button link type="primary" :disabled="!data.execution_enabled" @click="startApply(row)">应用</el-button><el-button link @click="toggle(row)">{{row.enabled?'暂停':'启用'}}</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="(readOnly?'查看':form.id?'编辑':'新增')+names[form.kind]+'模板'" width="min(1000px,95vw)" :close-on-click-modal="false"><el-form v-if="form.config" class="strategy-form" label-width="120px" :disabled="readOnly||busy"><el-form-item label="模板名称"><el-input v-model="form.name" maxlength="120"/></el-form-item><div class="two"><el-form-item label="适用站点"><el-select v-model="form.country" :disabled="!!form.id" placeholder="请选择适用站点" aria-label="适用站点"><el-option v-for="c in countries" :key="c" :value="c" :label="c"/></el-select></el-form-item><el-form-item label="模板状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="暂停"/></el-form-item></div><div class="two"><el-form-item label="生效日期"><el-date-picker v-model="form.config.start" value-format="YYYY-MM-DD" placeholder="不限"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.config.end" value-format="YYYY-MM-DD" placeholder="不限"/></el-form-item></div>
<template v-if="form.kind!=='inventory'"><el-form-item v-if="['bid','budget'].includes(form.kind)" :label="form.kind==='budget'?'基准预算':'基准竞价'"><el-radio-group v-model="form.config.baseline"><el-radio value="original">应用时的值</el-radio><el-radio value="fixed">固定值</el-radio></el-radio-group><el-input-number v-if="form.config.baseline==='fixed'" v-model="form.config.fixed" :min="form.kind==='budget'?1:0.02" :precision="2"/></el-form-item><el-form-item label="分时设置"><el-radio-group v-model="form.config.mode"><el-radio value="daily">按天</el-radio><el-radio value="weekly">按周</el-radio><el-radio value="calendar">日历模式</el-radio></el-radio-group><span class="muted">按广告账户当地时间</span></el-form-item><el-form-item label="时间段" class="schedule-field"><div class="schedule-list"><div v-for="(w,i) in form.config.windows" :key="i" class="window"><el-select v-if="form.config.mode==='weekly'" v-model="w.weekdays" multiple placeholder="星期" style="width:200px"><el-option v-for="(n,d) in weekdayNames" :key="d" :value="d" :label="n"/></el-select><el-date-picker v-if="form.config.mode==='calendar'" v-model="w.dates" type="dates" value-format="YYYY-MM-DD" placeholder="选择日期"/><el-input v-model="w.start" placeholder="08:00" style="width:86px"/>至<el-input v-model="w.end" placeholder="24:00" style="width:86px"/><el-select v-if="form.kind==='state'" v-model="w.state" style="width:110px"><el-option label="启用" value="ENABLED"/><el-option label="暂停" value="PAUSED"/></el-select><template v-else><span>调整</span><el-input-number v-model="w.percent" :min="-99" :max="900" :precision="1" style="width:120px"/>%<el-tooltip content="正数提高，负数降低，始终相对基准值计算"><span class="muted">ⓘ</span></el-tooltip><el-input-number v-model="w.minimum" :min="0.01" :precision="2" placeholder="下限" style="width:125px"/><el-input-number v-model="w.maximum" :min="0.01" :precision="2" placeholder="上限" style="width:125px"/></template><el-button link type="danger" @click="form.config.windows.splice(i,1)">移除</el-button></div><el-button @click="form.config.windows.push(newWindow())">＋ 添加时间段</el-button><p class="muted">{{form.kind==='state'?'未设置的时段暂停。':'未设置的时段恢复基准值。'}}{{form.kind==='budget'?'分时预算作用于广告活动。':''}}</p></div></el-form-item></template>
<template v-else><el-form-item label="库存口径"><el-checkbox-group v-model="form.config.inventory_fields"><el-checkbox value="available">FBA可售</el-checkbox><el-checkbox value="receiving">接收中</el-checkbox><el-checkbox value="inbound">入库中</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="暂停条件">库存小于 <el-input-number v-model="form.config.threshold" :min="0" :precision="0"/> 时暂停广告商品</el-form-item><el-form-item label="恢复条件">库存达到 <el-input-number v-model="form.config.restore_threshold" :min="form.config.threshold" :precision="0"/> 时启用广告商品</el-form-item><el-form-item label="执行时间"><el-radio-group v-model="form.config.inventory_frequency"><el-radio value="hourly">商品库存发生变化时（每小时检查）</el-radio><el-radio value="daily">每日定时</el-radio></el-radio-group><el-time-select v-if="form.config.inventory_frequency==='daily'" v-model="form.config.inventory_time" start="00:00" end="23:30" step="00:30"/></el-form-item><el-form-item label="执行方式"><el-radio-group v-model="form.config.execution"><el-radio value="auto">自动执行</el-radio><el-radio value="manual">人工确认后执行</el-radio></el-radio-group></el-form-item></template>
<el-form-item label="失效回调"><el-select v-model="form.config.rollback" style="width:220px"><el-option label="恢复应用前的值" value="original"/><el-option label="固定值" value="fixed"/><el-option v-if="['budget','bid'].includes(form.kind)" label="基准值乘以" value="multiple"/><el-option label="不回调" value="none"/></el-select><template v-if="['fixed','multiple'].includes(form.config.rollback)"><el-select v-if="['state','inventory'].includes(form.kind)" v-model="form.config.rollback_state" style="width:120px"><el-option label="暂停" value="PAUSED"/><el-option label="启用" value="ENABLED"/></el-select><el-input-number v-else v-model="form.config.rollback_value" :precision="2" :min="0.01"/></template></el-form-item><el-form-item class="rollback-note"><p class="muted">到期、暂停模板、取消应用或删除模板时执行回调。应用对象在“应用”中选择。</p></el-form-item></el-form><template #footer><el-button @click="dialog=false">关闭</el-button><el-button v-if="!readOnly" type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog>
<el-dialog :model-value="!!applying" title="应用策略" width="min(1000px,95vw)" @close="applying=null" :close-on-click-modal="false"><template v-if="applying"><p>{{applying.name}} · {{applying.country}} · {{names[applying.kind]}}</p><div class="apply-filters"><el-select v-model="applyStore" placeholder="店铺" @change="applyProfile='';choices=[];selected=[]"><el-option v-for="s in stores" :key="s" :value="s" :label="s"/></el-select><el-select v-model="applyProfile" placeholder="站点广告账户" @change="profileChanged"><el-option v-for="p in profiles" :key="p.id" :value="p.id" :label="p.country+' · '+p.id"/></el-select><el-select v-model="applyCampaign" placeholder="全部广告活动" clearable filterable @change="applyGroup='';loadChoices()"><el-option v-for="c in options.campaigns" :key="c.id" :value="c.id" :label="c.name"/></el-select><el-select v-if="['bid','inventory'].includes(applying.kind)" v-model="applyGroup" clearable placeholder="全部广告组" @change="loadChoices"><el-option v-for="g in groups" :key="g.id" :value="g.id" :label="g.name"/></el-select></div><el-input v-model="q" placeholder="搜索名称 / ASIN / SKU" clearable/><el-table :data="filtered" max-height="400" v-loading="busy" @selection-change="(v:any)=>selected=v"><el-table-column type="selection" width="45"/><el-table-column label="对象"><template #default="{row}">{{row.name}}<small class="muted"> {{row.asin}} {{row.sku}}</small></template></el-table-column><el-table-column prop="campaign_name" label="广告活动"/></el-table><p>已选择 {{selected.length}} 个对象，应用后按模板自动执行。</p></template><template #footer><el-button @click="applying=null">取消</el-button><el-button type="primary" :disabled="!selected.length" :loading="busy" @click="apply">确认应用</el-button></template></el-dialog>
<el-dialog :model-value="!!details" :title="details?.name+' · 应用记录'" width="min(1100px,95vw)" @close="details=null"><el-table v-if="details" :data="bindings(details)"><el-table-column prop="name" label="对象" min-width="190"/><el-table-column label="状态" width="100"><template #default="{row}">{{states[row.runtime.status]||row.runtime.status}}</template></el-table-column><el-table-column label="当前策略值" width="120"><template #default="{row}">{{row.runtime.last_value}}</template></el-table-column><el-table-column label="执行结果" min-width="250"><template #default="{row}">{{row.runtime.message||'等待执行'}}</template></el-table-column><el-table-column label="最近检查" width="180"><template #default="{row}">{{new Date(row.updated_at).toLocaleString()}}</template></el-table-column><el-table-column v-if="can('advertising','operate')" label="操作" width="150"><template #default="{row}"><el-button v-if="row.runtime.status==='pending'" link type="primary" @click="approve(row)">确认调整</el-button><el-button v-if="row.active" link @click="unbind(row)">取消应用</el-button></template></el-table-column></el-table></el-dialog>
</section></template>
<style scoped>.strategy-panel{padding:18px 22px;box-sizing:border-box}.heading{flex-wrap:wrap}.heading{display:flex;gap:12px;align-items:center;margin-bottom:15px}.heading h3{margin-right:auto}.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:24px}.window{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:12px;padding:12px;background:#f6f9f7}.apply-filters{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.apply-filters .el-select{width:220px}.muted{color:#84968d;font-size:12px;margin-left:8px}.strategy-panel :deep(.el-form-item__content){gap:10px}.strategy-form{max-height:70vh;overflow-y:auto;padding:4px 8px 0 0}.strategy-form :deep(.el-form-item){margin-bottom:20px}.strategy-form :deep(.el-form-item__label){padding-right:16px}.strategy-form :deep(.two .el-form-item__content){min-width:0}.strategy-form :deep(.two .el-select),.strategy-form :deep(.two .el-date-editor){width:100%;min-width:0}.schedule-list{width:100%;min-width:0}.schedule-list .window{margin-bottom:12px;padding:12px;border:1px solid #e4ede8;border-radius:6px}.schedule-list .muted,.rollback-note .muted{margin:8px 0 0;line-height:1.6}.strategy-form :deep(.schedule-field>.el-form-item__content){display:block}.strategy-form :deep(.el-radio-group){gap:4px 18px}.strategy-form :deep(.el-radio){margin-right:0}.strategy-form .rollback-note{margin-top:-12px;margin-bottom:0}@media(max-width:700px){.two{grid-template-columns:minmax(0,1fr)}.strategy-form :deep(.el-form-item__label){width:92px!important}.strategy-form :deep(.rollback-note .el-form-item__content){margin-left:92px!important}} </style>
